#[derive(Debug, Clone, PartialEq, Default)]
pub struct ObteBlock {
    /// `OBTE`, optional.
    pub obte: Option<Sub<Bytes>>,
    /// Group `ObtsEntry`, repeated.
    pub obts_entry: Vec<ObteBlockObtsEntry>,
    /// `STOP`, required.
    pub stop: Option<Sub<Bytes>>,
}

impl ObteBlock {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"OBTE",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ObteBlockObtsEntry::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"STOP",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.obte, subs, *index, "ObteBlock.OBTE", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = ObteBlockObtsEntry::default();
                    group.fill(hits, subs, ctx, extra);
                    self.obts_entry.push(group);
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.stop, subs, *index, "ObteBlock.STOP", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"OBTE", self.obte.as_ref());
        for group in &self.obts_entry {
            group.emit(out);
        }
        emit(out, *b"STOP", self.stop.as_ref());
    }
}

