        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"MODL", self.modl.as_ref());
        emit(out, *b"FLLD", self.flld.as_ref());
        emit(out, *b"EITM", self.eitm.as_ref());
        emit(out, *b"EAMT", self.eamt.as_ref());
        emit(out, *b"ETYP", self.etyp.as_ref());
        emit(out, *b"BIDS", self.bids.as_ref());
        emit(out, *b"BAMT", self.bamt.as_ref());
        emit(out, *b"PUSH", self.push.as_ref());
        emit(out, *b"PDSH", self.pdsh.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"DESC", self.description.as_ref());
        emit(out, *b"INRD", self.inrd.as_ref());
        emit(out, *b"APPR", self.appr.as_ref());
        if let Some(group) = &self.obte_block {
            group.emit(out);
        }
        emit(out, *b"NNAM", self.nnam.as_ref());
        emit(out, *b"BNAM", self.bnam.as_ref());
        emit(out, *b"WAIM", self.waim.as_ref());
        emit(out, *b"WAM2", self.wam2.as_ref());
        emit(out, *b"WAUD", self.waud.as_ref());
        emit(out, *b"WTUR", self.wtur.as_ref());
        emit(out, *b"WCHG", self.wchg.as_ref());
        emit(out, *b"WDMG", self.wdmg.as_ref());
        emit(out, *b"DAMA", self.dama.as_ref());
        emit(out, *b"WFIR", self.wfir.as_ref());
        emit(out, *b"WFLG", self.wflg.as_ref());
        emit(out, *b"WGEN", self.wgen.as_ref());
        emit(out, *b"WABB", self.wabb.as_ref());
